#!/usr/bin/env bash
# Copyright IBM Corp. 2024, 2026
# SPDX-License-Identifier: BUSL-1.1

# Local-binary runner for `peering` — starts TWO independent Consul dev
# agents (unlike every other scenario's one), both as local processes on
# 127.0.0.1 with distinct ports for everything. That's deliberate: on
# loopback, "reachable at 127.0.0.1:<port>" is trivially true for both
# agents, so a peering token generated by one and consumed by the other
# just works, with none of docker-compose.yml's static-subnet/advertise-IP
# gymnastics (see that file's comment for why Docker needs those).
#
#   ./local.sh up     # start node-primary (:8500, the fixed port
#                      # Playwright/ember talk to) + node-peer (:8510, only
#                      # seed.ts talks to it); seeding is done by seed.ts
#   ./local.sh down   # stop both
set -euo pipefail

CONSUL_BIN="${CONSUL_BIN:-consul}"
DIR="$(cd "$(dirname "$0")" && pwd)"
RUN_DIR="${RUN_DIR:-$DIR/.run}"

PRIMARY_PID_FILE="$RUN_DIR/agent.pid"
PRIMARY_LOG_FILE="$RUN_DIR/agent.log"
PEER_PID_FILE="$RUN_DIR/peer.pid"
PEER_LOG_FILE="$RUN_DIR/peer.log"

wait_leader() {
  local label="$1" port="$2" tries=30
  for ((i = 0; i < tries; i++)); do
    curl -sf "http://127.0.0.1:${port}/v1/status/leader" | grep -q '"' && return 0
    sleep 1
  done
  echo "$label did not elect a leader in time (checked :$port)"; exit 1
}

stop_pid_file() {
  local pid_file="$1" label="$2"
  if [[ -f "$pid_file" ]] && kill -0 "$(cat "$pid_file")" 2>/dev/null; then
    local pid; pid="$(cat "$pid_file")"
    kill "$pid"
    # `up` runs `down` first then immediately rebinds these ports — wait for
    # the real exit so a slow-to-die old process doesn't win the port race
    # (same gotcha as scenarios/auth-methods/local.sh).
    for ((i = 0; i < 20; i++)); do
      kill -0 "$pid" 2>/dev/null || break
      sleep 0.5
    done
    kill -0 "$pid" 2>/dev/null && { echo "$label $pid did not exit in time"; kill -9 "$pid" 2>/dev/null || true; }
    echo "stopped $label ($pid)"
  fi
  rm -f "$pid_file"
}

up() {
  mkdir -p "$RUN_DIR"
  command -v "$CONSUL_BIN" >/dev/null || { echo "consul binary not found (set CONSUL_BIN)"; exit 1; }
  down || true

  echo "starting node-primary (local) on :8500 ..."
  # Client/gRPC(-TLS)/Serf/server ports all explicit and distinct from
  # node-peer's below — the peering token bakes in the gRPC-TLS address, so
  # this has to be stable and known (see docker-compose.yml's comment; the
  # same reasoning applies here even without Docker's networking wrinkles).
  "$CONSUL_BIN" agent -dev -node node-primary -bind 127.0.0.1 -client 127.0.0.1 -dns-port=-1 \
    -http-port=8500 -grpc-port=8502 -grpc-tls-port=8503 \
    -serf-lan-port=8301 -serf-wan-port=8302 -server-port=8300 \
    > "$PRIMARY_LOG_FILE" 2>&1 &
  echo $! > "$PRIMARY_PID_FILE"

  echo "starting node-peer (local) on :8510 ..."
  "$CONSUL_BIN" agent -dev -node node-peer -bind 127.0.0.1 -client 127.0.0.1 -dns-port=-1 \
    -http-port=8510 -grpc-port=8512 -grpc-tls-port=8513 \
    -serf-lan-port=8311 -serf-wan-port=8312 -server-port=8310 \
    > "$PEER_LOG_FILE" 2>&1 &
  echo $! > "$PEER_PID_FILE"

  wait_leader "node-primary" 8500
  wait_leader "node-peer" 8510
  echo "consul dev agents started — node-primary PID $(cat "$PRIMARY_PID_FILE") (logs: $PRIMARY_LOG_FILE), node-peer PID $(cat "$PEER_PID_FILE") (logs: $PEER_LOG_FILE)"
}

down() {
  stop_pid_file "$PRIMARY_PID_FILE" "node-primary"
  stop_pid_file "$PEER_PID_FILE" "node-peer"
}

case "${1:-up}" in
  up) up ;;
  down) down ;;
  *) echo "usage: $0 {up|down}"; exit 1 ;;
esac
